import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [resultText, setResultText] = useState('');   // On utilise uniquement des strings
  const [errorText, setErrorText] = useState('');
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = { width: 1280, height: 720, facingMode: "user" };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setErrorText('');
    setResultText('');

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Impossible de capturer l'image");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 RAW RESPONSE:", response);
      console.log("📊 DATA:", data);

      if (data.success || data.student) {
        const name = String(data.student || data.student_name || data.name || "Inconnu");
        const confidence = (Number(data.confidence || 0) * 100).toFixed(1);
        setResultText(`✅ ${name} - Confiance: ${confidence}%`);
      } else {
        setErrorText(String(data.message || data.error || "Visage non reconnu"));
      }

    } catch (err) {
      const msg = err.response?.data?.error || err.response?.data?.message || err.message || "Erreur serveur";
      setErrorText(String(msg));
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={{ padding: 20, maxWidth: 700, margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center' }}>📷 Reconnaissance Faciale</h2>

      <div style={{ position: 'relative', borderRadius: 12, overflow: 'hidden', background: '#000' }}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={videoConstraints}
          style={{ width: '100%', height: 'auto' }}
        />
        {loading && (
          <div style={{
            position: 'absolute',
            inset: 0,
            background: 'rgba(0,0,0,0.75)',
            color: 'white',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '20px'
          }}>
            ⏳ Analyse en cours...
          </div>
        )}
      </div>

      <div style={{ marginTop: 20, display: 'flex', gap: 12 }}>
        <button 
          onClick={handleCapture} 
          disabled={loading || autoMode}
          style={{ flex: 1, padding: 14, fontSize: 16, background: '#4F46E5', color: 'white', border: 'none', borderRadius: 8 }}
        >
          {loading ? '⏳ Traitement...' : '🔍 Scan Manuel'}
        </button>

        <button 
          onClick={() => setAutoMode(!autoMode)}
          style={{ flex: 1, padding: 14, fontSize: 16, background: autoMode ? '#EF4444' : '#10B981', color: 'white', border: 'none', borderRadius: 8 }}
        >
          {autoMode ? '⏹ STOP AUTO' : '🔄 AUTO SCAN'}
        </button>
      </div>

      <div style={{ marginTop: 30, minHeight: 120 }}>
        {resultText && (
          <div style={{ padding: 16, background: '#DCFCE7', borderRadius: 10, fontSize: 18 }}>
            {resultText}
          </div>
        )}
        {errorText && (
          <div style={{ padding: 16, background: '#FEE2E2', borderRadius: 10, color: '#991B1B' }}>
            ❌ {errorText}
          </div>
        )}
      </div>
    </div>
  );
};

export default CameraRecognition;
